import { describe, it, expect, beforeEach } from 'vitest';
import { processCheckout, decrementInventory } from './checkout';
import { getInventory } from '../inventory/service';

describe('Checkout - Race Condition Fix', () => {
  beforeEach(() => {
    // Reset inventory state
  });

  it('should properly await inventory fetch before decrement', async () => {
    const productId = 'prod-123';
    const quantity = 2;

    // This should not throw undefined error
    await expect(
      decrementInventory(productId, quantity)
    ).resolves.not.toThrow();
  });

  it('should handle concurrent checkout requests', async () => {
    const productId = 'prod-456';

    // Simulate concurrent requests
    const requests = Array(10).fill(null).map(() => 
      processCheckout({ productId, quantity: 1 })
    );

    await expect(
      Promise.all(requests)
    ).resolves.toBeDefined();
  });
});
